                "dc.description" : [ {
                  "value" : "DATA AVAILABILITY : All data has been provided in the Supplementary Data Resource file and listed by country and/or ancestry. US-SEER data was downloaded from  https://seer.cancer.gov/data/access.html.",
                  "language" : null,
